#!/usr/bin/env bash
# Builds every client of the example from this checkout (snapshots are not published):
#   Java SDK and CLI    Maven (JDK 21 or later); the CLI as a JVM application, not native
#   Go SDK              nothing to build here: go-sdk/ is committed, go run compiles it (Go)
#   Python SDK          generated by Kiota, then pip installs it into python-sdk/.venv (Python 3.10+)
#   TypeScript SDK      generated and built in typescript-sdk/, then linked into typescript-sdk/ here (Node.js 22.18+)
# Usage: ./build.sh   (the first run takes a few minutes). SKIP=go,python,... skips clients, as in
# demo.sh. Maven reads extra arguments from MAVEN_ARGS.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../.." && pwd)
skip=",${SKIP:-},"
skipped() { [[ "$skip" == *",$1,"* ]]; }

modules=()
skipped java || modules+=(examples/registry-clients/java-sdk)
skipped cli || modules+=(cli)
if [ ${#modules[@]} -gt 0 ]; then
  echo "Building with Maven: ${modules[*]}"
  (cd "$root" && ./mvnw -q install -Pexamples -am -DcliSkipNative -pl "$(IFS=,; echo "${modules[*]}")" \
    -DskipTests -Dmaven.javadoc.skip=true -Dmaven.source.skip=true -Dassembly.skipAssembly=true)
fi

if ! skipped go; then
  echo "Downloading the Go SDK's dependencies"
  (cd "$here/go-sdk" && go mod download && go build -o /dev/null .)
fi

if ! skipped python; then
  echo "Installing the Python SDK (generated by Kiota first)"
  # kiota-gen.py generates apicurioregistrysdk/client in python-sdk/ unless it is there already:
  # remove it so the client always matches this checkout's OpenAPI document
  rm -rf "$root/python-sdk/apicurioregistrysdk/client" "$root/python-sdk/openapi.json"
  (cd "$root/python-sdk" && "${PYTHON:-python3}" kiota-gen.py)
  (cd "$here/python-sdk" && rm -rf .venv && "${PYTHON:-python3}" -m venv .venv \
    && .venv/bin/pip install -q --disable-pip-version-check "$root/python-sdk")
fi

if ! skipped typescript; then
  echo "Building the TypeScript SDK"
  (cd "$root/typescript-sdk" && npm ci --no-audit --no-fund --loglevel=error && npm run -s generate-sources && npm run -s build)
  (cd "$here/typescript-sdk" && npm ci --no-audit --no-fund --loglevel=error)
fi
